<script lang="ts">
  import { archiveOverview } from './overview';
  import { bytes } from './bridge';
  import type { ArchiveInfo,Entry } from './bridge';
  import type { ScanReport } from './scan';
  import { scanOutcome } from './scan';
  let {archive,sourceHintIds=[],scan=null,scanAvailable=false,busy=false,onpreview,onlocate,onfolder,onscan}:{archive:ArchiveInfo;sourceHintIds?:string[];scan?:ScanReport|null;scanAvailable?:boolean;busy?:boolean;onpreview:(entry:Entry)=>void;onlocate:(entry:Entry)=>void;onfolder:(path:string)=>void;onscan:()=>void}=$props();
  const overview=$derived(archiveOverview(archive.entries,sourceHintIds));
  const outcome=$derived(scan?scanOutcome(scan):null);
  const review=$derived(archive.findings.filter(f=>['error','warning','critical','danger'].includes(f.severity)));
  const blocked=$derived(review.some(f=>['error','critical','danger'].includes(f.severity)));
  let explain=$state(false), located=$state(false);
</script>

<div class="overview">
  <div class="identity"><img src="/icons/archive.svg" alt=""/><div><strong title={archive.name}>{archive.name}</strong><p>{overview.files} {overview.files===1?'file':'files'} · {overview.folders} {overview.folders===1?'folder':'folders'} · {bytes(archive.compressed_size)}</p></div></div>
  {#if archive.format.toLowerCase()==='mrar'}<span class="format-note">MRAR · Experimental · Keep originals</span>{/if}
  {#if overview.files}
    <div class="distribution" role="img" aria-label={overview.groups.map(g=>`${g.count} ${g.label}`).join(', ')}>{#each overview.groups as group}<span style:background={group.color} style:flex-grow={group.count} title={`${group.label}: ${group.count}`}></span>{/each}</div>
    <dl class="type-list">{#each overview.groups as group}<div><dt><span class="type-icon" style:color={group.color}><svg viewBox="0 0 20 24" aria-hidden="true"><path fill="currentColor" d="M3 0h9l6 6v15a3 3 0 0 1-3 3H3a3 3 0 0 1-3-3V3a3 3 0 0 1 3-3Z"/><path fill="var(--surface)" opacity=".65" d="M12 0v6h6Z"/></svg></span>{group.label}</dt><dd>{group.count}</dd></div>{/each}</dl>
  {/if}
  <section class="glance"><h3>At a glance</h3><p class="summary">{overview.summary}</p>
    {#if overview.folderRows.length}<div class="folder-chips">{#each overview.folderRows.slice(0,4) as item}<button title={item.path+'/'} onclick={()=>onfolder(item.path)}><img src="/icons/folder.svg" alt=""/><span>{item.path}/</span></button>{/each}{#if overview.folderRows.length>4}<span class="remaining">+{overview.folderRows.length-4}</span>{/if}</div>{/if}
    <div class="starting"><span>Likely starting file</span>{#if overview.main}<button disabled={busy} title={'Preview '+overview.main.name} onclick={()=>onpreview(overview.main!)}>{overview.main.name.split('/').pop()}</button>{:else}<span class="not-found">Not identified</span>{/if}</div>
    <p class="basis"><span aria-hidden="true">i</span>{overview.basis}</p>
  </section>
  <section class="explore"><h3>Explore this archive</h3><div class="actions"><button aria-expanded={explain} disabled={!overview.folderRows.length} onclick={()=>explain=!explain}>Explain folders</button><button disabled={!overview.main||busy} onclick={()=>{if(overview.main){onlocate(overview.main);located=true;}}}>Find main file</button></div>
    {#if located}<p class="located" role="status">Starting file selected in the file list.</p>{/if}
    {#if explain}<div class="folder-explanations">{#each overview.folderRows.slice(0,6) as item}<button onclick={()=>onfolder(item.path)} title={item.path}><strong>{item.path}/ <span>{item.count}</span></strong><small>{item.description}</small></button>{/each}{#if overview.folderRows.length>6}<small class="more-folders">{overview.folderRows.length-6} more folders in the explorer</small>{/if}</div>{/if}
  </section>
  <button class="scan-shortcut" disabled={!scanAvailable||busy} onclick={onscan}><img src="/icons/scan.svg" alt=""/><span class={outcome?'result '+outcome.state:blocked?'result blocked':review.length?'result attention':''}>{outcome?.title||(blocked?'Unsafe entries detected':review.length?`${review.length} ${review.length===1?'item':'items'} to review`:'Scan archive')}</span><span aria-hidden="true">›</span></button>
  <details class="more"><summary>More details</summary><dl><div><dt>Format</dt><dd>{archive.format.toUpperCase()}</dd></div><div><dt>Original size</dt><dd>{bytes(archive.total_size)}</dd></div><div><dt>Archive size</dt><dd>{bytes(archive.compressed_size)}</dd></div><div><dt>Password-protected files</dt><dd>{archive.entries.filter(e=>!e.is_dir&&e.is_encrypted).length}</dd></div></dl><p>Summary hints describe filenames, not verified contents.</p>{#if scan}<p>{scan.coverage.scanned_files}/{scan.coverage.total_files} files checked · {scan.coverage.complete?'Coverage complete':'Partial coverage'}</p>{:else}<p>Content scan has not run.</p>{/if}{#if review.length}<div class="review-details">{#each review.slice(0,8) as finding}<p>{finding.message}</p>{/each}{#if review.length>8}<p>{review.length-8} more inventory findings</p>{/if}</div>{/if}</details>
</div>

<style>
  .overview{font-size:12px;line-height:1.5;padding:0 0 12px}.identity{display:flex;align-items:center;gap:12px;margin-bottom:14px;min-width:0}.identity>img{width:38px;height:38px;flex-shrink:0}.identity>div{min-width:0}.identity strong{display:block;font-size:14px;line-height:1.4;white-space:nowrap;text-overflow:ellipsis;overflow:hidden;font-weight:650}.identity p{margin:5px 0 0;font-size:11px;color:var(--muted)}.format-note{display:block;color:var(--muted);font-size:10px;margin:-10px 0 16px}.distribution{height:8px;display:flex;gap:2px;overflow:hidden;border-radius:3px;margin-bottom:12px}.distribution>span{flex-basis:0;min-width:2px}.type-list{margin:0 0 12px}.type-list>div{display:flex;justify-content:space-between;align-items:center;min-height:28px;gap:12px}.type-list dt{display:flex;align-items:center;gap:11px}.type-list dd{margin:0;font-variant-numeric:tabular-nums;color:var(--muted)}.type-icon{width:17px;height:21px;display:inline-flex;flex-shrink:0}.type-icon svg{width:100%;height:100%}.glance,.explore{border-top:1px solid var(--line);padding-top:13px;margin-top:13px}.overview h3{font-size:12px;line-height:1.5;font-weight:650;margin:0 0 7px;letter-spacing:0}.summary{margin:0;color:var(--text);line-height:1.65}.folder-chips{display:flex;gap:6px;flex-wrap:wrap;margin:12px 0}.folder-chips button{display:inline-flex;align-items:center;gap:5px;min-width:0;max-width:135px;border-radius:4px;background:var(--soft);padding:4px 7px;font-size:10px;color:var(--muted)}.folder-chips button:hover{background:var(--selection);color:var(--accent)}.folder-chips img{width:13px;height:13px}.folder-chips button span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.remaining{font-size:10px;align-self:center;color:var(--muted)}.starting{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:6px;margin:11px 0;color:var(--muted);font-size:11px}.starting button{color:var(--accent);text-decoration:underline;text-underline-offset:3px;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;padding:2px 0}.not-found{font-size:10px}.basis{display:flex;align-items:center;gap:7px;font-size:10px;color:var(--muted);margin:8px 0 0}.basis>span{width:14px;height:14px;flex-shrink:0;border-radius:50%;background:var(--soft);color:var(--muted);font-size:10px;text-align:center;line-height:14px;font-weight:650}.actions{display:flex;gap:8px;margin-top:12px}.actions button{flex:1;border:1px solid var(--line);border-radius:5px;padding:8px 4px;color:var(--accent);font-size:11px;font-weight:550;white-space:nowrap}.actions button:hover:not(:disabled){background:var(--accent-soft)}.actions button:disabled{color:var(--muted)}.located{font-size:10px;color:var(--muted);margin:10px 0 0}.folder-explanations{border-left:2px solid var(--line);padding-left:11px;margin-top:14px}.folder-explanations button{display:block;text-align:left;width:100%;padding:6px 0;overflow:hidden}.folder-explanations strong{display:block;font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:550}.folder-explanations strong span{font-weight:400;color:var(--muted);margin-left:4px}.folder-explanations small,.more-folders{font-size:10px;color:var(--muted)}.scan-shortcut{display:flex;width:100%;align-items:center;gap:8px;border-top:1px solid var(--line);margin-top:13px;padding:10px 0;font-size:11px;text-align:left}.scan-shortcut img{width:17px;height:17px}.scan-shortcut>span:last-child{margin-left:auto;color:var(--muted);font-size:16px}.scan-shortcut .clear{color:#257248}.scan-shortcut .attention{color:var(--warning)}.scan-shortcut .blocked{color:#b43832}.scan-shortcut .incomplete{color:var(--muted)}.more{border-top:1px solid var(--line);font-size:10px;color:var(--muted);padding-top:13px}.more summary{cursor:pointer;font-size:11px;min-height:24px;list-style:none}.more summary:before{content:'›';display:inline-block;margin-right:10px;transition:transform .12s}.more summary::-webkit-details-marker{display:none}.more[open] summary:before{transform:rotate(90deg)}.more dl{margin:12px 0}.more dl>div{display:flex;justify-content:space-between;gap:12px;padding:4px 0}.more dd{margin:0;text-align:right;overflow-wrap:anywhere}.more p{line-height:1.6;margin:8px 0}.review-details{border-top:1px solid var(--line);margin-top:12px}.overview :global(button:focus-visible),.more summary:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.scan-shortcut:disabled{opacity:.65}
  :global(.application[data-theme=dark]) .scan-shortcut .clear{color:#79c99b}:global(.application[data-theme=dark]) .scan-shortcut .blocked{color:#f19b94}@media(prefers-color-scheme:dark){:global(.application[data-theme=system]) .scan-shortcut .clear{color:#79c99b}:global(.application[data-theme=system]) .scan-shortcut .blocked{color:#f19b94}}@media(prefers-reduced-motion:reduce){.more summary:before{transition:none}}
</style>
